INSERT INTO programme_subject_requirements (id, jamb_programme_id, utme_subjects, olevel_requirement, direct_entry) VALUES
  ('089fe82b-a3bc-592c-b3cc-1b7bd2613139', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'Any three (3) Arts or Social Science subjects.', 'Five (5)''O'' Level credit passes to include English Language, Literature in English and Mathematics.', '(i) Two (2)''A'' Level passes in Arts or Social Science subjects. (ii) NCE/ND/First Degree (Second Class Lower).'),
  ('43e111d0-fb57-575c-ab90-e62f38cb0ca2', '1c7b609c-1b60-5ab3-a3da-6a4e86d0e0a0', 'Any three (3) Arts or Social Science subjects including Arabic or Islamic Studies', 'Five (5)''O'' Level credit passes in Arts or Social Sciences to include English Language and Islamic Studies or Arabic.', 'Two (2) A'' level passes to include Islamic Studies or Arabic'),
  ('4fd43afb-6b06-500b-8992-116744626fbd', '288e06d8-b8e8-5ca0-8398-85a2b54b0183', 'Any three (3) Arts or Social Science subjects including Arabic or Islamic Studies', 'Five (5)''O'' Level credit passes in Arts or Social Sciences to include English Language and Islamic Studies or Arabic.', 'Two (2) A'' level passes to include Islamic Studies or Arabic'),
  ('d197f6e9-2020-5bd9-b61d-69f4b0ff47b4', '4a558a84-59f7-5496-b78e-59cce7c6d022', 'As in Civil Law', 'As in Civil Law', 'As in Civil Law'),
  ('8d37d653-64aa-5f7c-bcf9-bdf5ed4999a4', 'ba5512eb-56af-5b4d-b3cc-4732caed424b', 'Any three (3) subjects', 'Five (5)SSC credit passes to include English Language.', 'i. Two (2) ''A'' Level passes in Arts or Social Science subjects. ii. ND in Law, Criminal Justice, Public Administration with passes at lower credit or higher grade.'),
  ('f584c038-cc9e-5991-9cea-432eea3eca71', '35f1a5c5-9e87-5211-85cc-73bed5f1ccb0', 'Literature in English and any two (2) other Arts/or Social Science subjects.', 'Five (5)SSC credit passes to include English Language, Literature - in - English and any other three (3) Arts/Social Science subjects.', 'i. Two (2) ''A'' Level passes in GCE/IJMB in Arts or Social Science subjects. ii. First degree (Second Class Lower) of an accredited University.'),
  ('9667d01a-f266-5c15-bec9-9804a931716a', '6434f9f4-0658-5b87-91c7-f5eccbf02cc8', NULL, NULL, 'RSU accepts; Admissions into Year III; Degree relevant to the Programme. HND (Upper Credit) relevant to the Programme. Admissions into Year II; OND/ND (Upper Credit) in relevant discipline. HND (Lower Credit) in relevant discipline. Degree (Third Class) relevant to the programme.'),
  ('bd49a539-0eb7-5580-87c1-8eb72064870d', 'ffe0164e-e7be-5fb8-b356-397e0e0ab946', 'SALEM for Criminology requires Government and any two (2) of Economics, Geography and Literature in English.', NULL, NULL),
  ('186e511e-8d68-56e5-813c-bd3faa276db6', '2f24e362-4a88-5921-853a-d32c60d08aae', '(xxxiii) AAUA requires Economics, Mathematics and any other Social Science subject and for Criminology and Security Studies requires three (3) Arts or Social Science subjects. (xxxiv) FED-DUTSE: For Criminology and Security Studies, FED-DUTSE requires Economics, Government/Geography, Islamic Studies/CRS/Hausa or any other Arts subject.', '(x) AAUA: for Criminology and Security Studies, requires five (5) `O'' Level credit passes to include English Language, Government/History, Mathematics and two other subjects from Social Science/Arts. (xxiv) FED-OYE EKITI: For Criminology and Security Studies FED-OYE EKITI accepts five (5) SSC credit passes including English Language, Mathematics, Government and anyone from(Economics, Commerce, Geography and one Science or Arts subjects at SSC. (xxxviii) FED-DUTSE: For Criminology and Security Studies, FED-DUTSE accepts; five (5) `O'' Level credit passes SSC or its equivalent to include English Language, Mathematics with any two (2) Social Science subjects and any one Arts subject at not more than two (2) sittings.', NULL),
  ('3c1e7fb9-dc4c-55ed-b4a4-cf9b9a2623d1', 'c7f26eb8-056b-5d5f-841d-228767ebdb4d', 'Mathematics, Economics/Geography and any other subject.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, Government and any one of Geography or Biology', 'Two (2) ''A'' level passes in Geography, Economics, Government and Mathematics'),
  ('db74ae5a-c009-5ca8-a85b-5a34a57ec83a', '15ad2afd-ab3e-5174-a6e6-64960d49bbd2', NULL, NULL, NULL),
