  ('0719c080-2a7b-50e0-aab3-fb3d1d77b9a8', 'f430a8d2-ae24-5062-b7dc-df11bfdf79bf', 'Mathematics, Economics plus one other relevant subject', 'Five (5) SSC credit passes to include English Language and Mathematics.', 'i) Two (2) ''A'' Level passes chosen from Economics, Accounting, Government, Geography and Statistics. ii) NCE in related programme.'),
  ('b5698ce4-bbb4-53e1-8417-44cd05debae0', '581a3cd4-96f8-5341-a287-253b96f89ddf', 'Mathematics, Economics and one other subject.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics plus any two (2) subjects listed under the Direct Entry column.', 'Two (2) ''A'' Level passes chosen from Economics, Accounting, Business Management, Government, Geography and Statistics.'),
