  ('e110b8ce-61c8-54b1-adc9-343b7fc5724a', '5caf5d31-f105-5189-9702-1ce445589cfa', 'Two (2) ''A'' Level passes including Government or History.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Three (3) Social Science or Arts Subjects.'),
  ('82477a46-eae4-5ceb-add0-9e9fffcf909f', '733fb92a-6d77-57b6-b044-06102a212849', '(I) LAGOS requires English Language, two Social Sciences subjects and one Arts subject. **Mathematics is accepted. (ii) CALABAR and UNN require any three (3) Social Science or Arts Subjects. (iii) BENIN requires two (2) Social Science subjects and any other subject. (iv) PHC requires any three (3) others from Social Sciences (including Maths/Arts). (v) FED-LAFIA requires Economics, Government or History and any other Arts or Social Sciences subject.', 'Five (5) SSC credits including English Language and Mathematics.', 'Two (2) ''A'' Level passes in any subjects'),
  ('3bd9cd93-859b-5127-919b-4f9ed27eebf2', '72ba7675-519e-56c2-9d73-79b134a72c97', 'Three (3) Social Science or Arts subjects.', 'Five (5) SSC credit passes in Government or History, English Language and three (3) other subjects. A pass in Mathematics is required.', 'Two (2) ''A'' Level passes including Government or History.'),
  ('6b9a214f-39f5-5009-95b7-fb1e97a9a6d1', '759cdba9-d447-56d9-8bfe-aa8df075e8ea', '', '', ''),
  ('3d0bc2a0-223f-5b59-8d45-c20997837b97', 'b8be6f6c-9426-5b50-bef3-353ea9626f9c', 'Mathematics, Economics, plus any one (1) of Government and Geography.', 'Five (5) SSC credit passes to include: English Language, Mathematics and any other subjects. For NBC, the other two (2) relevant subjects could be from any of the following; Accounting, Principles of Accounts, Commerce, Office Practice and Economics.', 'Two (2) ''A'' Level passes chosen from Accounting, Economics, Management, Mathematics, Geography and Statistics.'),
  ('5f4aea5a-f3be-52cd-9262-b2553644d09c', '9d9c8373-bd9f-5382-b799-f9269ea0b1f9', NULL, NULL, 'OND (upper credit) or HND (Merit Pass) in Business Education, Business Studies, Business Administration, Marketing, Purchasing and Supply, Office Management, Secretarial Administration, Public Business Studies or Business Studies from any recognised institution, including UTME entry requirements. NCE with at least credit passes in Business Education, Business Studies, Business Administration, Marketing, Purchasing and Supply, Office Management, Secretarial Administration, Public Business Studies or Business Studies from any recognised institution including UTME entry requirements'),
  ('e766e8af-a811-5cc4-b23a-8a98815c10d9', '9f5b16dc-5db1-5559-afb5-b3fe5c8c6503', 'Government, Economics and any other subject.', 'Five (5) SSC credit passes to include English Language, Economics and Government. For NBC holders, the other relevant subjects could be from any of the following: Accounting, Principles of Accounts, Commerce, Office Practice and Secretarial Duties.', 'Two (2) `A'' Level passes chosen from Economics, Accounting, Business Management, Government, Geography and Statistics.'),
  ('bb8eaa60-24a6-54fe-994c-f5f64cc6b1d0', '933d3bcc-fa7b-580b-8fdb-06715cfad66e', 'Mathematics, Economics plus one (1) other subject.', 'Five (5) SSC credit passes including English Language, Mathematics and any three (3) relevant subjects.', 'Two (2) `A'' Level passes chosen from Accounting, Management, Government and Geography.'),
  ('48f26b7c-d790-56c3-b72c-787a1c62c930', '3eb75911-c3cc-5ab5-999f-d1b9994d9c6c', 'Economics, Mathematics and one (1) other Social Science or Commercial subject.', 'Five (5) SSC credit passes to include English Language, Mathematics, Economics, one (1) Science subject and one (1) other Social Science or Commercial subject.', 'Two (2) ''A'' Level passes to include Economics and one (1) of, Accounts, Business Management, Government, Geography or Mathematics.'),
  ('9eafc5d2-3ab4-5886-979d-86d9c92faeff', 'd90d594c-a36c-5e87-ac8d-6c73f6484d53', 'Mathematics, Economics and one (1) other subject.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics, plus any two (2) of Accounting, Business Methods, Commerce, Government, Geography, and Statistics.', 'Two (2) `A'' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.'),
  ('6509f2b1-79e7-5abd-83e5-5d95f7bb5216', 'f2c88d9c-d9bc-5328-97b7-02fb2d78a5ad', '(i) AAUA requires five (5) `O'' Level credit passes to include English Language, Mathematics, Economics and one Social Science Subject and any other Subject. (ii) AUN does not accept `O'' Level credit passes in the following; Agriculture, Food and Nutrition, Home Economics, Home Craft, Home Management, Physical Education, Physical and Health Education, Music, Commerce, Accounting, Financial Accounting, Book Keeping, Islamic Studies, History, Religious Studies, Tajweed, Library Studies, Diction, Kiswahili, Igbo, Hausa, Yoruba, Arabic, Turkish, Study Skills. (iii) AUN requires five (5) ''O'' Level credit passes including English Language, Mathematics, and any other three (3) subjects from the following: Economics, Geography, Government, History, Literature in English, Further Mathematics, Technical Drawing, Visual Arts, Computer Studies, Information Technology, Civics, Environmental Science, Biology, Physics, Chemistry and French. (iv) UYO, UNIZIK, ESUTECH, EKSU, IMSU and LAGOS require `O'' Level credit passes in Economics and two (2) other subjects. (v) EKSU requires `O'' Level credit passes in Economics plus other Social Science subjects. (vi) IMSU and BIU accept credit/merit in English Language in TC II. (vii) LAGOS requires `O'' Level credit passes in English Language, Mathematics, Economics and any two (2) of Government, Geography, Commerce, Financial Accounting, Physics, Chemistry, Biology, Business Management and Book Keeping. (viii) EBSU - Same as in Accounting. (ix) PHC requires Five (5) SSC credit passes to include English Language, Mathematics, Economics and any other two (2) subjects from Government/History, Geography, Commerce, Literature in English, CRK/IRK, Accounting (Financial/Business), Biology/Agricultural Science, Chemistry, Physics. (x) UNN requires five (5) `O'' Level credit passes to include: English Language, Mathematics and any other relevant subjects. For NBC the other two (2) relevant subjects could be from any of the following: Accounting, Principles of Accounts, Commerce, Office Practice and Economics. (xi) DELSU requires five (5) credits at SSC or its equivalent, obtained at not more than two (2) sittings, which must include English Language, Mathematics, Economics and any other two (2) Social Science subjects. (xii) RSU requires five (5) ''O'' Level credit passes to include English Language, Mathematics, Economics and any two (2) other subjects.', NULL, NULL),
  ('a4e3be07-a7ed-5402-8989-7f46f435bc3a', '8001154c-61d8-5d51-b22c-afdc7bfbcfa2', 'Mathematics, Economics plus one (1) other subject.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics plus any two (2) subjects listed under the Direct Entry column.', 'Two (2) ''A'' Level passes chosen from Economics, Accounting, Business Management, Government, Geography and Statistics.'),
  ('4061cd92-165a-5440-91aa-858e6f07d083', '86a02f6b-b048-58a5-a9f2-9417bea81ac3', 'Mathematics, Economics and any other subject.', 'Five (5) SSC credit passes including English Language, Mathematics and Economics.', '(i) ND/HND in relevant programmes. (ii) Degree/HND not relevant to the programme.'),
  ('2581d707-b69d-5d3f-b1ee-d58a705fbe70', '8a773366-6767-54d9-bd33-0394d7060c0e', 'Mathematics, Economics and one (1) other subject.', 'Five (5) SSC credit passes including English Language, Mathematics, Economics plus any two(2) of Accounting, Business Methods, Commerce, Government, Geography and Statistics.', 'Two (2) `A'' Level passes chosen from Economics, Accounts, Business Management, Government, Geography or Statistics.'),
