  ('e231cbab-927b-5fb6-a988-039aecb8516c', 'd3fafd50-ed55-551f-a405-2036e5705ff8', 'Government, Economics and any other subject.', 'Five (5) SSC credit passes to include English Language, Economics and Government. For NBC holders, the other relevant subjects could be from any of the following: Accounting, Principles of Accounts, Commerce, Office Practice and Secretarial Duties.', 'Two (2) `A'' Level passes chosen from Economics, Accounting, Business Management, Government, Geography and Statistics.'),
  ('775e6fd7-2fa3-509e-a2f7-7250dd443484', '8e5dc67d-9b56-56c2-855b-65bdebcfb61c', 'Mathematics, Physics and one (1) of Biology, Chemistry, Agric Science, Economics and Geography.', 'Five (5) SSC credit passes to include English Language, Mathematics, Physics plus two (2) other Science subjects.', '(i) Two (2) ''A'' Level passes in science subjects including Mathematics. (ii) NCE merit in Mathematics and one (1) other Science or Social Science subject.'),
  ('6c366336-54fd-56bb-95e3-eb4a69b2f264', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', 'Chemistry and two (2) of Physics, Biology and Mathematics.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology.', '(i) Two (2) ''A'' Level passes in Chemistry and any one (1) of Physics, Mathematics or Biology. (ii) ND/NCE with good grades in [continues beyond extracted range].'),
  ('11dc20ef-8ac6-5c15-ad81-ad3ca701d78e', '95470556-be8e-524a-84c9-c18631726722', 'Biology, Chemistry and either Physics or Mathematics.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Two (2) ''A'' Level passes in Chemistry and any one (1) from Biology, Zoology or Botany.'),
  ('40be9d0a-231d-5fbc-84a2-8648fb403ad6', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'Mathematics and any two (2) of Physics, Chemistry and any other science subject', 'Five (5) SSC credit passes including English Language, Mathematics and Physics or Chemistry and any other science subject', '(i) Two (2) ''A'' Level passes in Mathematics and any other science subject'),
  ('b4d03461-5881-5e3d-b7d8-1281266a91bb', 'a3ee8b52-f45a-562a-9f13-437e335f7229', 'Physics, Mathematics and Chemistry or Biology.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'NCE/Two (2) ''A'' Level passes in Physics and Mathematics or Chemistry.'),
  ('9eb5b9fa-229f-539b-8c80-a734550b1e04', 'c4b7c032-1249-5ba3-944f-317e7f02690f', 'Biology, Chemistry and Physics or Mathematics.', 'Five (5) SSC credit passes to include English Language, Biology, Chemistry and Mathematics/Physics.', '(i) Two (2) ''A'' Level passes from Chemistry, Biology, Botany/Zoology. (ii) NCE merit accepted.'),
  ('666c6c69-d2b3-5368-a90d-3da5f03ef379', '4a263b64-265b-59d3-a8e0-a003ded347aa', NULL, NULL, NULL),
  ('be4a0162-d806-5a58-98bf-791c6f2dc359', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'Mathematics and any two (2) of Physics, Chemistry and Economics.', 'Five (5) SSC credit passes to include English Language, Mathematics and at least three (3) subjects from Physics, Statistics, Chemistry, Further Mathematics, Economics and Geography.', 'Two (2) ''A'' Level passes to include Mathematics or Statistics. NCE credit in relevant subjects.'),
  ('f89d68fc-a20a-5dc4-bcfd-935b063cc349', 'e5fc1bb0-45a9-5551-ad53-b3cb017a7359', NULL, NULL, NULL),
  ('daedf323-d863-5ea2-80d9-39c701001343', 'e846688d-5a41-5cff-a100-601250655f22', NULL, NULL, NULL),
  ('3070b963-ccb3-5f27-8e60-d770e8a41623', '017ce18b-858a-54ec-a868-66509b88f6df', 'Any three (3) of Chemistry, Physics, Mathematics, Biology and Geography.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and any other subject.', 'Two (2) ''A'' Level passes from Geology, Chemistry, Mathematics, Physics, Biology and Geography.'),
  ('9f18b556-5cf4-5ad9-a72a-2b334da93fcf', 'f223fc44-85c1-5b06-b837-4829600cb07b', NULL, NULL, NULL),
  ('755d568f-6219-56b1-9288-00d2161ee166', '4b0e8d62-6287-5ae5-a79b-1aa3f88216f5', 'Biology and any two (2) of Physics, Chemistry and any other Science subject', 'Five (5) SSC credit passes in English Language, Mathematics, Biology and two (2) other Science subject', 'Two (2) ''A'' Level passes or NCE in Biology, Zoology or Botany and one other Science subject'),
  ('8a738836-91ae-5e61-b3a6-ac8741b0d877', '0f6edcb0-1c1c-5881-a00c-419e0cdd213a', 'Biology, Chemistry and any other Science subject.', 'Five (5) SSC Credit passes in English Language, Mathematics, Biology, Chemistry and Physics.', 'Two (2) ''A'' Level passes in Biology/Botany/Zoology and Chemistry or Physics.'),
  ('b2b52289-49fc-5929-a4d7-585e3a3e2bb9', 'bdedc35f-6a08-5ca7-9398-f8818c464155', 'Mathematics and any two (2) of Physics, Chemistry, Economics, Biology and Agricultural Science.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics and two (2) other Science subjects.', '(i) Two (2) ''A'' Level passes from Mathematics, Physics, Economics or Chemistry. (ii) NCE merit in relevant subjects.'),
  ('0f6cfdcf-eef8-5a08-b331-8bfa6d3f164c', '959c3ba4-8dda-50ee-b8a9-391b51f9c593', NULL, NULL, NULL),
  ('784eccab-6c3b-5dbe-943d-ac5136238c04', '140a7d02-4cff-5c38-b809-8e5433ca6e5f', 'Chemistry, Mathematics and any of Physics/Biology/Agricultural Science.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Physics and Biology/Agricultural Science.', '(i) Two (2) ''A'' Level passes in Chemistry and Mathematics (ii) ND in Science Technology or ND in relevant programmes with the UTME requirements.'),
  ('fbb15f8d-87b2-5a7a-9e58-552ce731a93d', '002f7c01-edcc-5312-b688-57cd1641db05', 'UDU and FUTA accept Agricultural Science in lieu of Biology; UNIOSUN, SALEM, MAKURDI and BENIN require Biology, Chemistry and Physics; CALABAR and UYO require Physics as the third subject; EVANGEL and AJAYI require Biology and Chemistry and any other Science subject; UNIOSUN requires Mathematics, Biology and Chemistry; FED-DUTSE (a) For Microbiology requires Biology, Physics and Chemistry, (b) For Environmental Management and Toxicology requires Chemistry, and two of Physics, Biology and Mathematics.', 'Five (5) ''O'' Level credit passes (varies by institution; see waivers). Note: column shared across grouped Microbiology/SLT/Environmental programmes. Typical: English Language, Mathematics, Chemistry, Biology and Physics.', 'Varies by institution (see waivers). Note: heading lists option set with options in: 1. Biological Science Technique, 2. Biotechnology Technique, 3. Biochemistry Technique, 4. Chemistry Technique, 5. Geology Technique, 6. Microbiology Technique, 7. Physics/Electronics Technique, 8. Physiology/Pharmacology Technique, 9. Petrochemical Technique.'),
  ('ab341725-bc28-59a9-8832-dcbac0572254', '55f56132-bba6-5a31-b47f-9f5c3ad3e46b', NULL, NULL, NULL),
  ('5b19bb3f-2215-5cea-8400-e742744ff6e0', '1ff950fd-bd82-5844-8b39-9a4da052d231', 'Biology, Chemistry and Physics or Mathematics. UTME SUBJECT (i) MAUTY and FUTA require, Chemistry, Biology/Agricultural Science and either Mathematics or Physics. (ii) AUE accepts Mathematics, Chemistry and Physics. (iii) OAUSTECH accepts Agricultural Science in lieu of Physics and Mathematics. (iv) FUTO requires Biology, Chemistry and Physics/Mathematics. (v) ABU requires Use of English, Biology, Chemistry, and Physics. (vi) KASU requires Biology, Chemistry and two other Science subjects.', 'Five (5) SSC credit passes to include English Language, Mathematics, Chemistry, Biology and any other Science subject. UTME: (i) UNN - as in combined courses. (ii) MAKURDI accepts ''O'' Level pass in English Language. (iii) BSU requires ''O'' Level credit passes in English Language, Physics or Geography. (iv) OOU accepts ''O'' Level credit pass in any other subject from Physics and Geography. (v) NDU requires the five (5) ''O'' Level credit passes at not more than two (2) sittings. (vi) BAUCHI requires ''O'' Level pass in Physics. (viii) PAAU, FED-LOKOJA, OAUSTECH and CRUTECH require ''O'' Level credit pass in Physics as the fifth (5th) subject. (ix) FUNAAB require five (5) ''O'' Level credit passes to include English Language, Mathematics, Chemistry, Biology and Physics. (x) FUTA requires five (5) ''O'' Level credit passes in English Language, Mathematics, Physics, Chemistry, Biology or Agricultural Science at not more than two (2) sittings. (xi) GOUU requires five (5) ''O'' Level credit passes at not more than two (2) sittings in subjects which must include English Language, Mathematics, Chemistry, Physics and Biology. (xii) NDA requires one (1) other Science subject from Physics, Further Mathematics or Agricultural Science. (xiii) FUTO requires five (5) `O'' level credit passes in English Language, Chemistry, Mathematics, Physics and Biology in not more than two (2) sittings. (xiv) ABU requires Five `O'' level credit passes in English Language, Mathematics, Biology, Chemistry and Physics. (xv) KASU requires Five `O'' level credit passes to include English Language, Mathematics, Biology, Chemistry and one other Science subjects.', '(i) Two (2) ''A'' Level passes to include one (1) of Botany, Zoology, Biology or Chemistry. (ii) ND/NCE in related programme/subject.'),
  ('c9355a6f-5c39-5921-8172-4ca25e2163fd', 'f5cf1fd2-fec2-5f39-ace9-b976ed995e8f', NULL, NULL, NULL),
  ('45987a61-af31-5c04-862d-a3c6443ce14c', 'e994716d-9be0-5275-b87d-7c79f080038d', NULL, NULL, NULL),
  ('74bc647e-10ab-52ff-92e5-7eacf2de849b', '50039f37-748b-5d8e-b90c-4ed2d030b882', 'MADONNA and EBSU accept ''O'' Level pass in Physics with ''O'' Level credit pass in Mathematics; IMSU, COOU, UYO and EBSU accept ''O'' Level pass in English Language. (UTME subjects column shared with grouped block; see waivers.)', 'Five (5) ''O'' Level credit passes (varies by institution). FED-DUTSE: for Environmental Management and Toxicology accepts English Language, Mathematics, Chemistry, Geography and Biology or Agric. Science (max two sittings) plus at least pass in Physics. CUAB: English Language, Mathematics, Chemistry and Geography with pass in Physics, Biology and Agricultural Science. BSU for Microbiology accepts passes in five prescribed subjects in Preliminary Science of BSU.', 'Varies by institution (see waivers); column shared with grouped block.'),
  ('4ec7114a-426f-5075-bc7f-96bfd6dbeffc', '6938302f-81fd-5fba-8e26-dbefb5a40357', '(i) AAU and EKSU require Mathematics. (ii) OAU requires Chemistry, Mathematics and either Biology or Physics. (iii) ILORIN requires Biology, Chemistry and Physics. (iv) SALEM, MAKURDI, OAUSTECH, OAUSTECH and BENIN require Biology, Chemistry and Physics. (v) BOWEN requires Chemistry and any two (2) of Physics, Mathematics and Biology. (vi) AJAYI - Same as Chemistry. (vii) BELLS does not require Biology in lieu of Mathematics. (viii) WESTERN-DEL requires Biology, Chemistry, Physics and Mathematics. (x) FUTA requires Chemistry, Biology/Agricultural Science and Mathematics/Physics. (xi) KWASU requires Chemistry, Biology plus any one (1) of Physics, Mathematics and Further Mathematics or Geography. (xii) CUAB and SAU require Biology, Chemistry and Physics/Mathematics. (xii) OAUSTECH requires Chemistry, Biology and Physics. (xiii) SOUTHWESTERN – Same as Microbiology. (xiv) UNIOSUN requires Mathematics, Chemistry and Physics. (xv) NILE accepts any three (3) Science subjects. (xvi) FED-DUTSINMA requires English Language, Biology, Chemistry and Mathematics or Physics. (xvii) DELSU requires Biology, Chemistry and Physics. (xviii) FED-GASHUA accepts Biology, Chemistry, Physics/Mathematics. (xix) AAUA requires Biology, Chemistry and Physics. (xx) FED-DUTSE accepts Chemistry, Biology and Physics. (xxi) RSU requires Mathematics, Biology Chemistry. (xxii) MAIDUGURI requires Chemistry and any two (2) of Biology, Mathematics and Physics. (xxiii) FED-OYE EKITI requires Biology, Chemistry and Physics. (xxiv) FUTO requires Biology, Chemistry and Physics/Mathematics. (xxv) FED-WUKARI requires Biology, Chemistry and any of Physics or Mathematics. (xxvi) CARITAS requires Physics, Chemistry, Biology. (xxvii) MAUTY requires Biology, Chemistry and Physics or Mathematics. (xxviii) LAGOS requires English Language, Biology, Chemistry and Physics. (xxix) FED-LOKOJA requires Biology, Chemistry, and Mathematics/Physics. (xxx) ABU requires Use of English, Biology, Chemistry, and Physics. (xxxi) PHC requires Biology, Chemistry and Physics or Mathematics. (xxxii) FED-KASHERE requires Biology, Chemistry and any of Physics or Mathematics. (xxxiii) KASU requires Biology, Chemistry and one other Science subject. (xxxiv) LANDMARK requires Biology, Chemistry and Physics or Mathematics.', 'UTME: (i) FUTA requires five (5) five SSC credit passes or its equivalent at a maximum of two (2) sittings in the following subjects: English Language, Mathematics, Physics, Chemistry, Biology/Agricultural Science. (ii) OAU accepts Physics or Biology. (iii) ABSU requires ''O'' Level credit pass in Physics. (iv) IMSU and COOU accept ''O'' Level pass in English Language. (v) UMUDIKE same as in Food Science and Technology. (vi) NDU requires five (5) ''O'' Level credit passes at not more than two (2) sittings. (vii) CRUTECH- Same as Biological Science. (viii) AJAYI requires five (5) ''O'' Level credit passes which must include English language, Mathematics, Chemistry, Physics, and Biology at one (1) sitting or six (6) ''O'' Level credit passes at not more than two (2) sittings. (ix) MAIDUGURI accepts ''O'' Level passes in English Language and Mathematics. (x) CUAB accepts ''O'' Level credit pass in Agricultural Science in lieu of Biology. (xi) EBSU requires ''O'' Level credit pass in Mathematics or Physics. (xii) BELLS require five (5) ''O'' Level credit passes in English Language, Mathematics, Chemistry, Physics, Biology/Geography/Further Mathematics/Agricultural Science. (xiii) REDEEMER''S requires five (5) ''O'' Level credit passes in English Language, Mathematics, Chemistry, Physics and Biology/Agricultural Sciences. (xiv) WESTERN-DEL requires five (5) ''O'' Level credit passes which must include Chemistry, English Language, Biology, Mathematics and Physics. (xv) PLASU – Same as in Chemistry. (xvi) GOUU accepts ''O'' Level credit pass in any other Science subject in lieu of Physics. (xvii) KWASU accepts ''O'' Level credit passes in Further Mathematics and Agricultural Science. (xviii) RENAISSANCE requires (5) five ''O'' Level credit passes at not more than two (2) sittings. (xix) MAKURDI - Candidates seeking admission into any of these programmes must possess five (5)''O'' Level credit passes from one (1) examination body (i.e. either WAEC or NECO) and obtained at not more than two (2) sittings. The department does not accept the combination of both WAEC and NECO. Students of the University of Agriculture, Makurdi Pre-degree Remedial Science Programme who pass their end of session examinations are considered for admission on the condition that they also pass the UTME. NOTE: Agricultural Science and Health Science shall not be accepted in place of Biology. Further Mathematics shall not be accepted in place of Physics or Mathematics. (xx) SAU accepts ''O'' Level credit passes in Technical Drawing, Agricultural Science or Geography in lieu of Physics. (xxi) UMYUK requires five (5) ''O'' Level credit passes at not more than two (2) sittings. (xxii) SOUTHWESTERN – Same as Microbiology. (xxiii) LANDMARK accepts in lieu of Physics ''O'' Level credit passes in any of the following subjects: Further Mathematics, Technical Drawing, Agricultural Science, Food and Nutrition. (xxiv) SOSU accepts HND lower credit or ND upper credit in Science Laboratory Technology, Food Science Technology or its equivalent. (xxv) ODUDUWA accepts ''O'' Level credit pass in Agricultural Science or Health Science in place of Biology. (xxvi) FED-DUTSINMA accepts Five `O'' level Credits including: English Language, Mathematics, Physic, Chemistry and Biology. (xxvii) UNIKINGS accepts five (5) credits at SSC in English Language, Chemistry, Physics, Mathematics and Biology. (xxviii) EUI requires five (5) credit passes at SSC or its equivalent in English Language, Mathematics, Chemistry, Physics and Biology at not more than two (2) sittings. (xxix) DELSU requires five (5) `O'' Level credits and must include English Language, Mathematics, Physics, Chemistry and Biology. (xxx) FED-GASHUA requires five (5) SSC credit passes in English, Mathematics, Biology, Chemistry, Physics. (xxxi) AAUA requires five (5) `O'' Level credit passes to include English Language, Biology, Chemistry, Physics and Mathematics. (xxxii) FED-DUTSE requires five (5) ''O'' Level credit passes at SSC level or its equivalent to include Englsih Language, Mathematics, Biology, Chemistry and Physics. (xxxiii) RSU requires five (5) ''O'' Level credit passes to include English Language, Mathematics, Biology, Physics and Chemistry. (xxxiv) MOUNTAIN TOP requires five (5) credit passes at SSC or its equivalent to include English Language, Mathematics, Biology, Chemistry and Physics at not more than two (2) sittings. (xxxv) FUTO requires five (5) `O'' level credit passes in English Language, Chemistry, Mathematics, Physics and Biology in not more than two (2) sittings. (xxxvi) ILORIN requires five (5) `O'' Level Credit passes in English Language, Mathematics, Physics, Chemistry and Biology. (xxxvii) FED-WUKARI requires Candidates must obtain Five (5) Credits at not more than two sittings including English Language, Mathematics, Chemistry, Biology and any one from the following subjects; Physics/Agricultural Science/Health Science/Animal Husbandry obtained from Senior School Certificate(SSCE), National Examination Council(NECO), National Business and Technical Examination Board(NABTEB) or its equivalent. (xxxviii) CARITAS requires Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and Biology or Agricultural Science. (xxxix) MAUTY requires Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology. (xl) LAGOS requires Five O/Level credit passes in English Language, Mathematics, Biology, Chemistry and Physics. (xli) FED-LOKOJA requires Five (5) SSC credit passes to include English Language, Mathematics, Physics, Chemistry and Biology. (xlii) ABU requires Five `O'' level credit passes in English Language, Mathematics, Biology, Chemistry and Physics. (xliii) PHC requires Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Physics and Biology. (xliv) FED-LAFIA requires Five (5) Credit passes at SSCE, GCE, NECO and NABTEB O'' Level examination in Mathematics, English Language, Biology, Chemistry and Physics in not more than two sittings. (xlv) FED-KASHERE accepts Five credit passes at SSCE (or its equivalent) in English, Mathematics, Chemistry, Physics and Biology. (xlvi) KASU accepts Five `O'' level credit passes to include English Language, Mathematics, Biology, Chemistry and Physics. (xlvii) LANDMARK accepts Five (5) SSC credit passes in English Language, Chemistry, Mathematics, Biology and one of the following Physics, Agricultural Science, Food and nutrition.', '(lix) FUTO requires; a) At least two (2) `A'' Level passes not below Grade C in Chemistry and Biology. b) ND/HND at Upper Credit level in life sciences. c) First Degree in life sciences. d) Very good passes in three JUPEB subjects namely Chemistry, Biology and Physics or Mathematics. It does not accept NCE. Candidates must in addition meet the `O'' Level requirements.'),
  ('ca9e945c-d469-5359-84f7-20abb56c38b9', '7493e43d-840e-53d8-abdc-edfc478ff965', 'Any three (3) of Physics, Chemistry, Biology and Mathematics.', 'Five (5) SSC credit passes including English Language, Mathematics, Physics and Chemistry/Biology.', '''A'' Level passes in Chemistry and Physics or Mathematics.'),
