  ('6fa5fdac-2f1f-5073-9672-7844e053a276', '9e01b512-d680-5fae-9ac6-d0f06b213354', 'Physics, Mathematics and Physics, Chemistry or Biology.', 'Five (5) SSC credit passes in English Language, Physics, Chemistry, Mathematics and any other Science subject from Further Mathematics and Biology or Agricultural Science.', 'Two (2) ''A'' Level passes in Physics and Mathematics.'),
  ('38d053fe-0ca7-5f15-b988-e70f5b71107f', 'd56482a6-7894-53b9-92e6-99e4c8104249', NULL, NULL, NULL),
  ('cf6fed7a-7348-5817-a360-fa896767e69d', 'b71ed565-d14f-5c9b-9d3a-e87ba7673e46', 'Geography and one (1) other science subject. Mathematics, Geography and any other two (2) Science subjects.', 'Five (5) SSC credit passes to include English Language, Mathematics, Geography and any two (2) of Biology, Chemistry, Physics and Agricultural Science.', 'Two (2) ''A'' Level passes in Geography and one (1) other science subject.'),
  ('18a196c4-6ae6-5bf9-acef-2ccf50def5c4', 'a692ff81-1f9e-526d-a07b-f3dad21b728e', 'Maths, Physics and Chemistry or Biology and Additional/Further Mathematics.', 'Five (5) SSC credit passes to include English Language, Mathematics and at least three (3) of Physics, Chemistry, Biology and Additional/Further Mathematics.', '(i) Two (2) ''A'' Level passes in Mathematics and either Physics or Chemistry. (ii) NCE merit in Mathematics and either Physics or Chemistry.'),
