  ('a158fa47-8ddd-5efb-9fb7-663e1de90879', 'a019e508-bd9e-5657-92fd-9ca3c5438230', 'Chemistry, and Biology Physics or Mathematics.', 'Five (5) SSC credit passes in English Language, Mathematics, Chemistry, Biology and Physics.', 'Two (2) ''A'' Level passes in Chemistry and Biology or Health Science.'),
  ('9e91575b-998b-5690-9408-d5a63b3af0ad', 'a086a771-8f00-500f-8d2c-4b9ac8a28aeb', NULL, NULL, NULL),
  ('bef1f117-7647-5f8b-8a78-cf5c2c44aafb', '265e08d0-c76a-5667-a596-b2ee306d36bc', 'Chemistry, and Biology Mathematics or Physics.', 'Five (5) SSC credit passes in English Language, Biology, Chemistry, Mathematics and any other subject. ''O'' Level pass in Physics is required.', '(i) Two (2) ''A'' Level passes in Chemistry and Biology. (ii) NCE/HND credit in Biology or Agricultural Science for 200 level.'),
  ('aa0d1e29-9c08-50d9-b19e-4366d89bfc84', 'fdf7044f-eabf-5597-9bee-379cb6d2833d', NULL, NULL, NULL),
  ('719b3fa9-b359-5de4-b0f1-8df000eb4e44', '68604374-fc17-5739-8049-80ec9aaf8941', 'Physics, Mathematics, and any of Chemistry, Geography, Art, Biology and Economics.', 'Five (5) SSC credit passes in English Language, Mathematics, Physics, Chemistry and any of Fine Art, Geography or Wood Work, Biology, Economics, Technical Drawing, Further Mathematics, Introduction to Building Construction, Bricklaying/Block Laying, Concreting, Wall, Floors and Ceiling Finishing, Joinery, Carpentry, Decorative Painting, Lining, Sign & Design, Wall Hanging, Colour Mixing/Matching & Glazing, Ceramics, Graphics Design, Graphic Printing, Basic Electricity.', '(i) Two (2) ''A'' Level passes chosen from Mathematics or Physics and Chemistry, Geography or Fine Arts. (ii) ND/HND upper credit in relevant programmes.'),
  ('c4bc86ff-56ad-585e-9ca7-c0b0edd033a7', 'f38c02f1-1057-5c5f-89f0-36f16f694559', NULL, NULL, NULL),
  ('dbf2f89d-c269-58dc-adac-f437aa5581b6', '7029bc09-8585-5b15-ad6c-dfe5103bea89', NULL, NULL, NULL),
  ('90163d22-b409-5cb5-850c-98b2f9711389', 'f9586ba1-e66b-5aff-9b92-64960c868dea', 'OAU require Mathematics, Physics and Chemistry; CALABAR does not accept Biology; FUPRE requires Physics, Mathematics and Chemistry; FED-OYE EKITI requires Physics and Mathematics, Chemistry or Biology; OAUSTECH requires Physics, Mathematics and any one of Chemistry, Biology and Geography; FUTA requires Physics, Mathematics and Chemistry; MOUNTAIN TOP requires Physics, Mathematics and any one of Chemistry/Biology/Agricultural Science/Geography; FUPRE requires Mathematics, Chemistry and Physics; ILORIN requires Physics, Mathematics and Chemistry; LAGOS requires English Language, Mathematics, Physics and Chemistry; FED-KASHERE requires Physics, Chemistry and Mathematics.', 'Five ''O'' Level credit passes. OAU: English Language, Chemistry, Biology/Further Mathematics, Mathematics and Physics. FUTA: English Language, Physics, Mathematics, Chemistry and one of Biology/Geography/Technical Drawing (max two sittings). FUPRE: English Language, Biology, Mathematics, Physics and Chemistry. FED-OYE EKITI: English, Mathematics, Physics and Chemistry. OAUSTECH: English Language, Physics, Chemistry, Mathematics and Biology/Geography. LAGOS: English Language, Mathematics, Physics, Chemistry and Biology. ILORIN: English Language, Physics, Mathematics, Chemistry and one of Further Mathematics/Biology/Geography. FED-KASHERE: English, Mathematics, Physics, Chemistry and any of Further Mathematics/Geography/Biology. (heading begins before line range; this programme is partial)', 'National Diploma (Upper Credit) in Electrical Engineering, Petroleum Engineering, Geology and Mining, Physics or Computer Science (one option visible at top of range).'),
  ('4ec700d4-7921-5c1d-833e-c11d6cfd7621', '9d8a051b-aeb8-5fc7-a0ab-a1a68ab7e0d2', NULL, NULL, NULL)
