INSERT INTO school_programmes (id, school_id, jamb_programme_id, remarks) VALUES
  ('dd87eeac-3e62-5b50-be7e-edb50ec79ddf', 'd27d7d4c-dcf3-5254-9faa-94e2991a92e3', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (ii) ABU accepts Two `A'' Level/IJMB Passes in English Literature and other Arts or Social Science subjects. ABU Diploma in Law with at least MERIT Grade. ABU Diploma in Shari''ah and Civil Law with at least Merit Grade. | UTME: (xxv) ABU requires Five `O'' Level Credit passes which must include English Language, Literature in English and any other three Arts or Social Science Subjects. | UTME SUBJECTS: (xv) ABU requires Use of English, Literature in English and any other two Arts or Social Science subjects.'),
  ('694c92cf-746b-55fb-af15-31f30f75edd4', '0b2a9d40-1151-53c2-afa0-dda8f622ef86', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (xix) OOU accepts a degree in Arts or Social Sciences not lower than a second class lower plus the basic UTME requirements. | UTME: (xiii) JOS and OOU; ''O'' Level credit pass in Mathematics is not compulsory. | UTME: OOU requires ''O'' Level credit pass in Literature in English and at least ''O'' Level pass in Mathematics. | UTME SUBJECTS: (vi) OOU does not insist on Literature in English.'),
  ('8f3c47e1-2268-5ef6-9353-cba4cf7f505d', '3a9f0243-a4ff-53cc-aa6f-bc01c43451d7', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (xxiv) UNIZIK accepts a) HND with credits or distinction aggregates from recognised institution and at least five (5) ''O'' Level credit passes which must include English Language, Mathematics, and/ or any other science subject. b) NCE/Degree plus the UTME requirements.'),
  ('97a63fc1-4864-5005-8b52-2fcfd5c04edb', '929f28a0-ddd3-5a6a-8e8f-90942af20ac0', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (i) AAU does not accept any Diploma and NCE but accepts only first degree second class lower plus the UTME requirements. AAUA requires ''O'' Level credit passes in Literature in English and Mathematics. | UTME: (i) AAU and NAU require ''O'' Level credit pass in one (1) science subject and one (1) commercial subject and at least ''O'' Level pass in Mathematics. | UTME SUBJECTS: (i) BOWEN, ILORIN, UNN, BENIN, AAU and OAU require Literature in English plus any two (2) subjects.'),
  ('f88d50d9-1a61-5b93-af1c-604688b47f91', '89224bf1-f265-5d8d-8994-83b751cf73e5', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (i) ... AAUA requires ''O'' Level credit passes in Literature in English and Mathematics. | UTME: (xxii) AAUA requires five (5) `O'' Level credit passes to include English Language, Literature in English, Mathematics and any other two subjects from, CRK /IRS, Igbo Language/Yoruba Language/Hausa Language, History, Economics, Geography, Commerce, Accounts/Book-keeping and Government. | UTME SUBJECTS: (x) AAUA accepts Literature in English and any two (2) subjects in Art/Social Science.'),
  ('a6fb3d98-9710-53ce-9ca9-7e5257e30822', '0a0013b5-4b5a-5144-a156-8d2db266ce65', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', NULL),
  ('c9b02023-72b4-52f8-b23c-c824f3892ac9', '4beb9b46-ddaa-5a56-b936-ea60e63b57c9', 'fabf6801-11dc-5f0f-ae97-f6380e89c6af', 'DIRECT ENTRY: (iii) ABUAD accepts excellent passes in JUPEB subjects. | UTME: (ii) ABUAD accepts five (5) ''O'' Level credit passes to include English Language, Literature in English, Mathematics and any two (2) Arts or Social Science subjects at one sitting. | UTME SUBJECTS: (xiii) ABUAD requires Literature in English and any two Arts or Social Science subjects.'),
