  ('1ded53d5-3f38-55c3-aada-aff79e4a3d19', '89224bf1-f265-5d8d-8994-83b751cf73e5', 'b1ad7931-2328-5191-8727-d1af3e46802c', 'DIRECT ENTRY (vii) AAUA requires: a. Registered Nurse/midwifery Certificate plus credit in Bio/Health Science/General Science b. National Diploma at upper credit level in Social Work, applied Psychology, Criminology and Security studies c. A'' level passes in Economics, Geography or Government. | UTME (xi) AAUA accepts five (5) `O'' Level credit passes to include English Language, Mathematics and Biology and two Social Science subjects. | UTME SUBJECTS (xiii) AAUA requires three (3) Social Science subjects.'),
  ('39a6535e-b900-5885-b612-a81d19187c00', '4beb9b46-ddaa-5a56-b936-ea60e63b57c9', 'b1ad7931-2328-5191-8727-d1af3e46802c', NULL),
