  ('45f38c25-36c9-5be7-9440-271f822536b7', 'b142037f-159e-5166-9da1-a41ab005569c', '72ba7675-519e-56c2-9d73-79b134a72c97', '(iv) UDU accepts ND credit in Mass Communication and NCE Social Studies.'),
  ('3554637b-6c02-5522-b67f-9c68f5c6586f', '929f28a0-ddd3-5a6a-8e8f-90942af20ac0', '72ba7675-519e-56c2-9d73-79b134a72c97', '(xiv) AAU accepts two (2) ''A'' Level passes from Mathematics, Economics, Government and Geography.'),
  ('e894aaa1-fbee-5c31-85ad-d754717c59a8', '89224bf1-f265-5d8d-8994-83b751cf73e5', '72ba7675-519e-56c2-9d73-79b134a72c97', '(viii) AAUA accepts ND upper credit in relevant programmes. Requires ''A'' Level passes in Government and one Social Science subject.'),
