  ('24db18af-fb21-546d-b6da-f1228040a29e', 'd567a2a1-0e09-50e6-a549-8ebc1a86367d', '933d3bcc-fa7b-580b-8fdb-06715cfad66e', 'EVANGEL and DELSU - As in Banking and Finance. | UTME SUBJECTS: EVANGEL accepts Mathematics or Economics plus any two (2) relevant Arts or Social Science subjects.'),
  ('431c25a1-6f4e-5381-a1d2-992539b5e14c', 'cc548faf-07a4-5541-93c3-535da80d4d5e', '933d3bcc-fa7b-580b-8fdb-06715cfad66e', NULL),
