  ('0d877d08-7361-553c-bb5f-e3ec9a5fc6c3', 'eb2b773f-8ee4-5799-ac95-143c6394f4d9', '933d3bcc-fa7b-580b-8fdb-06715cfad66e', 'UTME SUBJECTS: MAIDUGURI requires Mathematics, any of Principles of Accounting/Commerce/Economics and any other Social Science subject.'),
  ('d103c44c-01e0-5329-8ec0-59eaffb88dd0', 'c6fc829e-08df-5b24-ad29-f0fcd8e09a0b', '933d3bcc-fa7b-580b-8fdb-06715cfad66e', NULL),
