  ('e13b94a6-a8d0-5d2d-90a1-aa069d5294ee', 'be4981eb-2b54-5ea1-941d-44e8ca2774db', '8001154c-61d8-5d51-b22c-afdc7bfbcfa2', 'DIRECT ENTRY (ii) ILORIN accepts ND in Management Studies at upper credit, ND in Industrial Relations & Personnel Management OR Human Resource Management at upper credit from any recognized institution in addition to meeting the UTME requirements.'),
