  ('86cd9b9d-0634-54d3-8bd1-924d3bc017dc', '862dfbdf-bc8b-58e0-9031-c4c30cb2b315', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', '(xl) CRUTECH accepts a) For Chemistry ND upper credit in Science Laboratory Technology, HND lower credit in Food Technology, NCE merit in Chemistry and any other Science subject, IJMB B grade in Chemistry and any other Science subject. b) For Biochemistry ND upper credit in Science Laboratory Technology, HND lower credit in Food Technology, NCE merit in Chemistry and Biology, IJMB B grade in Chemistry and Biology.'),
