  ('be9945cc-3c2a-5375-9b0d-379522769319', '1c45a50a-ca0e-54eb-9f35-3be6de7b2e83', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', '(xxvii) NDA requires one (1) other Science subject from Biology or Further Mathematics.'),
  ('b8e36e16-40a4-5912-9a92-82f7e52bafb3', 'bfd398ad-cc0f-5245-bf71-04505c05d507', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', 'NDU accepts ND upper credit in Chemistry or any of the Sciences or Applied Sciences, e.g. Engineering, etc or NCE merit. Higher ND HND in Chemistry and in addition must have five (5) ''O'' Level credit passes obtained at not more than two (2) sittings in English Language, Mathematics, Physics, Chemistry and Biology. | (xxiv) NDU requires the five (5) ''O'' Level credit passes at not more than two (2) sittings.'),
  ('df4df0e7-73e5-505e-8a40-5ba2ffec1476', 'af407f01-76c5-535e-bc37-82d3bb1e1fde', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', NULL),
