  ('1b6e17b1-0067-5d94-bb69-07f593071c16', '9563ec0e-64c3-5553-97d2-48342fdf18fc', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', 'NILE - Same as in Computer Science. | (xviii) NILE accepts English Language, Mathematics, Chemistry and any other two (2) Science subjects. | (vi) NILE - Same as in Computer Science.'),
  ('5da611fa-1b6e-5111-aeaf-4f2ed44ce5e1', '3c13885c-9b61-5e63-a6d1-c5f8b9ae2266', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', '(i) RHEMA, OAU, UNN, OOU, BENIN, EKSU and BOWEN do not accept Biology. | (i) RHEMA, OAU, UNN, OOU, BENIN, EKSU and | (iv) IBADAN, UNN, LAGOS and OAU do not accept ND/NCE. | (vi) OAU and AAU accept any other subject in lieu of Biology. | OAU and IBADAN - As in Chemistry. | OAU, DELSU, EBSU, FUTO, BELLS, FUTA require Mathematics, Physics and Chemistry'),
  ('bb2a4c76-2034-5959-ba0b-56eb4006913f', 'fe45832b-9a35-5f0b-bde4-8b7379a5c683', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', '(xxx) ODUDUWA accepts ''O'' Level credit pass in Agricultural Science or Health Science in place of Biology. | (xvi) ODUDUWA accepts Agricultural Science in place of Biology'),
  ('dfa7798d-380a-5eac-be75-21afbc1fe0c3', '0b2a9d40-1151-53c2-afa0-dda8f622ef86', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', '(i) RHEMA, OAU, UNN, OOU, BENIN, EKSU and BOWEN do not accept Biology. | (i) RHEMA, OAU, UNN, OOU, BENIN, EKSU and | (xiv) OOU requires Chemistry and any two (2) of Physics, Mathematics, Biology, Agricultural Science and Geography. | OOU requires Chemistry and any two (2) of Physics, Mathematics, Biology, Agricultural Science and Geography.'),
  ('2ee957ae-b30b-5f93-b08b-78ad69ad9725', 'cd0c8006-ec78-5cd6-a51c-ba8884601a74', '7cc8cb7b-c778-52e8-8203-a1cba35e5eba', NULL),
