  ('307bdfb4-764c-5eea-a8d5-2458d0d7581c', 'd567a2a1-0e09-50e6-a549-8ebc1a86367d', '95470556-be8e-524a-84c9-c18631726722', 'Accepts NCE or ND in related programme in addition to UTME requirements.'),
  ('9bda4a3f-64d5-50eb-89b5-7202ab5742a1', '75eaf007-a369-56a4-a009-832b8a0efd89', '95470556-be8e-524a-84c9-c18631726722', 'Accepts (a) For Microbiology: two (2) ''A'' Level passes (Graded A-D in GCE A level, NCE, IJMB or OND) in relevant subjects (Biology, Botany, Chemistry and Physics) with minimum 8 points; ND upper credit in related discipline (Science Laboratory Technology, Medical Laboratory Science, Microbiology, Biotechnology), Nursing Diploma at Pass level. (b) For Environmental Management and Toxicology: GCE ''A'' Level, IJMB, NCE minimum of Credit Pass or OND minimum of Lower Credit (total minimum score of eight points); NCE and OND courses with bias in Applied Sciences.'),
  ('c5d5376c-fe32-5f23-bd02-c953bc2f6e26', '4b90c4e5-c0ba-525e-9663-8fe5ce07e7c5', '95470556-be8e-524a-84c9-c18631726722', 'Accepts Two ''A'' level passes in Botany/Zoology/Biology and Chemistry. ND/NCE with good grades in any relevant field.'),
  ('aa705485-d4f9-593e-bce8-7cbb8129dbde', 'df55ed4b-dcd1-522b-985b-afd17113826f', '95470556-be8e-524a-84c9-c18631726722', NULL),
