  ('fa6682b3-84a9-5bf7-a8d9-edd61627ea79', 'cc548faf-07a4-5541-93c3-535da80d4d5e', '95470556-be8e-524a-84c9-c18631726722', 'Accepts Three ''A'' Level passes in Biology and any other two of Chemistry, Physics, Mathematics, Botany and Geography OR minimum of 9 points in IJMB, 10 points in NCE with credit pass in the subject of specialization OR at least a Merit pass in relevant Diploma. Must satisfy ''O'' Level requirement.'),
  ('7254d2f4-36f9-5281-8176-bdf7e56aec7c', '4b767c85-a5d3-5578-b266-246db57463f3', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('65131251-1989-587d-9780-0f8fd2af556f', '7f1e09fa-66eb-50d0-b12b-a66eecc30366', '95470556-be8e-524a-84c9-c18631726722', 'Accepts DE candidates with any of: IJMB minimum 9 points in Biology and any two of Chemistry, Mathematics or Physics; GCE A'' Level with Credit pass in Biology or Botany and at least two from Chemistry, Mathematics and Physics; ND Lower credit in Science Lab. Tech and Food Technology; HND in Microbiology, Biotech or Biochemistry; NCE Merit with Credit Pass in Integrated Science. (Same for Microbiology.)'),
  ('9bf57abe-736b-5ee4-8a04-55e8f5c1ce42', '363063fa-a46e-5ffa-82be-96d75945a3b9', '95470556-be8e-524a-84c9-c18631726722', 'Accepts in addition to UTME Entry Requirements: Two (2) ''A'' Level passes to include one of Botany, Zoology, Biology or Chemistry; IJMB minimum of 8 points; NCE Credit pass in Chemistry and Biology; ND upper credit in Biological Science, Science Laboratory Technology or related programmes; HND lower credit in relevant programmes; Degree (Third Class) relevant to the programme.'),
  ('c73bb939-714a-5df9-9dce-902e78bf4b3a', 'a7537f3d-dd55-5419-9e59-c906e666b2e9', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('17ef4bfe-5f76-585e-ad0b-fb449e0f5a4f', 'cf90707a-389f-5ef7-9550-3e51de569ee2', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('02dd2cad-1eca-5592-bb73-dcb34a94745d', 'cd4edfad-172a-5f76-b45e-f806306ef788', '95470556-be8e-524a-84c9-c18631726722', 'Direct Entry candidates in addition to five (5) credits at SSC, obtain a minimum of upper credit in OND in a relevant Biological Science course, minimum of ''B'' grade in Physics, Chemistry and Biology in IJMB and overall ''B'' grade in relevant courses or subjects in NCE.'),
  ('5ada43ef-4098-5111-b3d4-0f2506b0784b', '494e4fb9-006d-55e9-86f2-caf559cdfb7d', '95470556-be8e-524a-84c9-c18631726722', 'For Microbiology accepts Direct Entry candidates with at least two ''A''/Level passes in relevant Science subjects which must include Biology, Chemistry, Botany/Geography/Mathematics/Physics at GCE A/level, IJMB/Advanced NABTEB or merit pass at NCE or at least a credit in OND/HND in relevant fields. Must also satisfy UTME admission requirements of Five Credits including English Language and Mathematics.'),
  ('48403921-4bb8-5c11-9509-0dfd8698954c', '83fac53f-1976-54e9-8d52-216198517c81', '95470556-be8e-524a-84c9-c18631726722', NULL),
