  ('68a33de7-061d-59fc-b729-e8952fce1ebd', '4c09fbbb-db34-5412-b132-dddd968310f6', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('e4daab83-e9a7-577f-be68-a331e86b4b00', '24904785-a0d6-5cd1-bbac-c78dbc9bbf6b', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('80c8a410-f73e-57d0-96a7-5ce726cc74b1', 'b89a3b5b-70cd-560a-a574-4d8bb5a6e43d', '95470556-be8e-524a-84c9-c18631726722', 'Same as in Environmental Science. Requires two (2) ''A'' Level passes in Biology and any one of Chemistry, Physics or Mathematics; accepts ND in Biology and Chemistry.'),
  ('6a9eeb53-bf0b-5988-98d9-0bd0c7fe4bde', 'ef542dde-3868-5cfe-8785-9ba7c46a333a', '95470556-be8e-524a-84c9-c18631726722', NULL),
  ('5303fded-3e73-5d8b-a8d7-39e474ed9c08', '929f28a0-ddd3-5a6a-8e8f-90942af20ac0', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DIRECT ENTRY: accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry. | Accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry.'),
  ('b713ab71-7c34-5b2f-b91f-53e4013cd665', '89224bf1-f265-5d8d-8994-83b751cf73e5', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: (a) two (2) ''A'' Level passes in GCE or the Higher School Certificate (HSC) or any recognized equivalent in not more than two sitting; subjects should include Mathematics, Physics/Chemistry; (b) Diploma from other recognized Universities with at least an Upper credit/credit level pass in Mathematics/Statistics, Mathematics and Education, Diploma in Computer Science and Science Laboratory Technology; (c) HND with at least lower credit level pass in Mathematics, Statistics or Computer Science or SLT in relevant area; (d) NCE with at least credit level pass in Mathematics and Statistics/Economics, Computer Science Study, candidates should have at least overall credit level pass; (e) Bachelor of Science degree in any of the disciplines in Physical Sciences with at least 3rd Class Honours. O''level: requires five (5) ''O'' Level credit passes to include English Language, Mathematics, and any three from Physics/Economics, Chemistry, Biology/Agricultural Science. UTME: accepts Mathematics, Physics, and any one of Chemistry, Biology/Agricultural Science and Economics.'),
  ('6f59c024-35a7-5e2a-8099-3703d1eab97b', 'd27d7d4c-dcf3-5254-9faa-94e2991a92e3', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts Two ''A'' level/IJMB passes in Mathematics and any one of Chemistry, Physics, Biology, Geography and Geology; NCE Mathematics and any of Chemistry, Physics, Biology, Geography, Geology and Computer Science. O''level: requires Five ''O'' level credit passes in English Language, Mathematics and Physics and two other subjects two of which must be sciences (Chemistry, Physics, Biology, and Geography), Computer Science/Data Processing. UTME: requires Use of English, Mathematics and any two of Chemistry, Physics, Biology and Geography.'),
  ('3e908a26-a8ec-535b-a210-ba8971095ae9', '4beb9b46-ddaa-5a56-b936-ea60e63b57c9', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('35252d2a-b491-595e-87e1-270d9d448efb', '0a0013b5-4b5a-5144-a156-8d2db266ce65', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'No Direct Entry Admission. ABSU accepts ND upper credit and HND lower credit plus the UTME requirements. UTME: IMSU and ABSU require Physics; IMSU accepts ''O'' Level pass in English Language. ABSU requires five (5) ''O'' Level credit passes including English Language, Mathematics and Physics or Chemistry and any two (2) subjects.'),
  ('8a0a7021-0cc7-55d1-b706-45699eef68bc', '3160c1ef-48e4-50a9-bc6b-358612396197', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts two (2) ''A'' Level passes in Mathematics and either Physics and/or Chemistry OR NCE minimum 10 points with credit in Mathematics and another Science subject OR ND upper credit in relevant programme in addition to the UTME requirements. O''level: accepts five (5) ''O'' Level credit passes or equivalent including English Language, Mathematics and any other three (3) subjects preferably Further Mathematics, Physics, Chemistry, Biology/Agricultural Science and Geography in that order. UTME: accepts Biology as one (1) of the other two (2) subjects.'),
  ('c10aa804-13cb-5098-8a5c-75101e161514', '74af1bf6-a9c3-5b8c-95d3-1c7b82810803', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
