  ('557a02ad-fa4d-5230-9305-fbb1fc3b57b9', '2efe249d-d745-5228-b7ce-a9d51f310389', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: requires two (2) ''A'' Level passes in Mathematics and Physics and/or Chemistry; accepts NCE with five (5) ''O'' Level credit passes including Mathematics and Physics or equivalent. O''level: requires five (5) ''O'' Level credit passes or equivalent including English Language, Physics and Mathematics and any other two (2) subjects from Further Mathematics, Physics, Chemistry, Biology, Agricultural Science. UTME: requires Mathematics and Physics, and one (1) of Chemistry, Biology, Geography and Economics in the order of preference.'),
  ('1210e6b4-72ba-5fe5-87c8-aa651d7c40e9', '7a8822e3-ea27-54fe-a564-9638023073a4', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
