  ('9ff75db3-ca02-5f50-ac6b-cce7125dcd0b', 'a868159d-9676-5217-8e97-e9986cdcad57', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: (a) Two ''A'' level passes in Mathematics and any other science subject; (b) NCE with at least merit in Mathematics and one of Physics, Chemistry; (c) accepts Biology; (d) does not accept Economics. O''level: requires five (5) SSCE credit passes including English Language, Mathematics and the remaining from Physics, Chemistry and Geography. UTME: requires Mathematics and any two (2) of Physics, Chemistry and Geography.'),
  ('5bde4051-9bd7-55b0-a064-e3a2cdeb2052', '7b5e2930-09df-5b45-b6e4-706d02fface6', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('db27b34c-8801-5358-acfe-02e236279b66', 'b3b5ba8a-6573-57f7-b4f1-11c42e383729', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts DME merit in addition to the UTME requirements; also accepts ND upper credit/HND lower credit in Mathematics/Statistics or Science Laboratory Technology in relevant subjects, and NCE merit with ''O'' Level credit pass in Mathematics or Physics. UTME: requires Physics, Chemistry, Mathematics and one (1) of Biology, Agricultural Science, Economics or Geography for Mathematics. For Industrial Mathematics - requires five (5) ''O'' Level credit passes in English Language, Mathematics and any three (3) subjects. Accepts Mathematics, Physics and any of Chemistry, Biology or Agricultural Science.'),
  ('d427bee2-b9a8-54d9-be55-5cde89611eb6', 'e8c6808a-0849-5b97-9a52-9ee5acde35cd', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('3651ff88-1cd2-5738-8bee-553949b84f93', 'ef954b01-0ec7-50cc-a305-64443a125b58', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'Accepts ND/NCE upper credit in relevant programme.'),
  ('0bf7c5b9-8e47-520a-9e6c-14f7a6c9efc4', '67373fa5-6882-5745-84c3-c752448ab6f1', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('6ffadf2f-bf13-5998-bf5a-272b4b9b39ec', '2d6c0715-8ce0-5c73-b289-c540c4e50cea', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('aa487f51-3ff1-594b-a344-97fdcc1d1cdd', '4d2eede5-c18d-57fa-b36b-8863e6580ae3', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts ''A'' Level/IJMB/NCE/ND or approved equivalent in Mathematics and any one (1) of Biology, Chemistry, Economics, Statistics and Physics. UTME: does not allow a combination of Biology and Agricultural Science but accepts Mathematics and any other two (2) Science subjects. (with CRUTECH, KWARARAFA: accept Mathematics, Physics and two (2) other Science subjects). (BINGHAM, BOWEN, EBSU require Mathematics and any two (2) of Physics, Chemistry and Biology; do not accept Geography.) | Accept Mathematics, Physics and two (2) other Science subjects. CRUTECH UTME requires Mathematics, Physics and any of Biology, Chemistry and Geography.'),
  ('aa1a4557-8c91-5ba7-8248-91e1121dc414', '80fa8795-5ba9-5984-8fe2-c09146280362', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('1478c8e4-e700-5e8c-925b-06bb41bd4450', '2a323993-11a4-5569-905d-e90b89ee3bc7', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DIRECT ENTRY: accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry. | Accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry. | Accept English Language, Mathematics, Physics, Chemistry, and any other relevant Science subject. | UTME requires Mathematics, Physics and any of Chemistry or Biology.'),
  ('fe3236ae-f768-5ba7-809e-053b03875525', 'dc4f0a5d-b0bd-5a7a-84e2-a4406fe8dfd8', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
