  ('cbd74b7e-af89-5df8-a2f6-3a178a694186', 'b1b4fc19-3e74-5955-bddd-ac63ab9e1ad6', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts Two (2) A level passes in Mathematics and any other science subject; NCE merit in Mathematics and one (1) of Physics, Chemistry or Economics. O''level: requires Five (5) SSC credit passes including English Language, Mathematics, Physics or Chemistry and any other two (2) Science Subjects. UTME: requires Mathematics and any two (2) of Physics, Chemistry and Economics or Geography.'),
  ('7c7c6245-4cb4-5ffd-bdc2-97766e0e41bd', '937e7bda-af27-5c2a-b0f9-8088491f8dbc', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('83231af3-aea9-5c2c-af9e-6d1b835b7972', '980bbe04-8ef6-5eab-a60f-ef76f3203594', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: (a) Two (2) ''A'' Level passes or its equivalent, one (1) of which must be in a relevant subject; (b) ND upper credit in relevant programme; (c) HND lower credit in relevant programme; (d) NCE credit in relevant subjects may be considered for Direct Entry Admission provided they possess the necessary ''O'' Level requirements. O''level: requires ''O'' Level credit passes from English Language, Mathematics and any three (3) of Biology, Physics, Chemistry, Further Mathematics and Agricultural Science. UTME: requires English Language, chosen course and any two (2) from Physics, Chemistry, Biology and Further Mathematics.'),
  ('b9ef7e9a-568f-5f3e-8a0b-64c93d42288c', '26ce26b0-5eac-5286-b8b5-179e56a6b320', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts very good passes in three (3) JUPEB/''A''-level subjects: Physics, Mathematics and any one (1) of Chemistry, Biology, Economics and Geography; requires ''O'' level credit pass in Further Mathematics. Does not accept NCE. O''level: requires five O/Level credit passes in English Language, Mathematics, Further Mathematics, Physics and any one of Economics, Chemistry and Geography. UTME: requires English Language, Mathematics, Physics and any of Chemistry, Economics, Biology and Geography.'),
  ('b24f99ca-e469-5f1f-b560-44b739e8f4ef', '94269d25-a8ea-57a9-9abf-8089f0510ebd', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: accepts Two (2) A level passes in Mathematics and any other science subject; NCE merit in Mathematics and one (1) of Physics, Chemistry or Economics. O''level: requires Five (5) SSC credit passes in English Language, Mathematics, Physics, and any other two science subject or one science subject and one social science subject. UTME: requires Mathematics and any two (2) of Physics, Chemistry, Biology, Economics, Agricultural science, Computer science and Data processing.'),
  ('aa4e3314-5f52-5097-ab7d-95d3a427838c', '0e92a1a7-c46a-50ff-a1cb-8f958376dcfe', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
