  ('f2b994e4-7b5f-59f3-a546-92cdeef04054', '1c45a50a-ca0e-54eb-9f35-3be6de7b2e83', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'Requires five (5) ''O'' Level credit passes from English Language, Mathematics, Physics and any two (2) from Chemistry, Further Mathematics and Biology.'),
  ('e71a9eeb-ef08-59b6-b965-3c040238e4ac', 'bfd398ad-cc0f-5245-bf71-04505c05d507', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'No Direct Entry Admission. ABSU accepts ND upper credit and HND lower credit plus the UTME requirements. UTME: IMSU and ABSU require Physics; IMSU accepts ''O'' Level pass in English Language. ABSU requires five (5) ''O'' Level credit passes including English Language, Mathematics and Physics or Chemistry and any two (2) subjects. | Accept Economics. | Requires five (5) ''O'' Level credit passes in English Language, Mathematics, Physics, Chemistry, and any other Science subject. UTME (with BSU): require Mathematics and any two (2) of Physics, Biology, Chemistry and Geography.'),
  ('28d4e132-ae86-5e2f-9427-b8885a158ff4', '4df9e055-3b05-5de1-925e-17c74753828b', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('9453ac28-40c1-5cb0-ac3a-fd959438cbb5', '3c13885c-9b61-5e63-a6d1-c5f8b9ae2266', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DIRECT ENTRY: accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry. | Accept Mathematics and Physics or Chemistry. EKSU does not accept NCE for Direct Entry. | Do not accept NCE. | Accepts English Language, Mathematics and any two (2) of Physics, Chemistry, Biology and Additional Mathematics.'),
  ('0ce392e0-e456-52b1-8723-198defed2dd5', '5a750e5a-581d-55a6-90e2-f9dd7dbb970a', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('7b8d3960-6e2a-5098-8713-7be4a6ac0962', '0b2a9d40-1151-53c2-afa0-dda8f622ef86', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'Do not accept NCE.'),
  ('97d49de1-1bcb-5587-9829-65c426cfd9dc', 'cd0c8006-ec78-5cd6-a51c-ba8884601a74', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('20717014-bc87-5c5e-9ef0-ab6456a8f75a', 'e7c05fd4-6b0d-50f2-9179-d7c7be0a45a1', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: (a) two (2) ''A'' Level passes in Mathematics and any one (1) of Physics, Chemistry, Biology, Economics and Geography; ND distinction and credit in relevant programmes. O''level: requires five (5) ''O'' Level credit passes in English Language, Mathematics, Physics, plus at least two (2) from Chemistry, Biology and Further Mathematics. UTME (with SOUTHWESTERN): require Mathematics, Physics and any one (1) of Chemistry or Biology.'),
  ('7ecdc2ef-3f20-5fa6-8ae2-8999e9f584df', 'f7c295d5-15f5-5895-a7d5-2c348521c2cc', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'Requires ''O'' Level credit passes at not more than two (2) sittings including English Language, Mathematics, Physics or Chemistry or Biology. UTME requires Mathematics, Physics and Biology/Agricultural Science/Chemistry/Geography.'),
  ('bdafe733-7170-54ee-a1fd-5e50360e1ecb', 'b79e4328-0416-574b-9b73-a0dd6b1642d6', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
