  ('af66f074-1acf-5875-bfac-8ce7bab4b2e3', '7a4e0c52-76d5-5817-aa59-6bc6fd09c7dc', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
  ('52118a4a-b6a3-536d-a95a-01c8633e5e77', 'bf0a9b2b-9fd6-5e7e-9c88-6c372119fa86', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', 'DE: (f) degree in any programme provided the candidate meets the UTME requirements; (g) HND lower credit in relevant programmes with the UTME requirements; (h) ND lower credit in relevant programme with the UTME requirements; (i) IJMB minimum of seven (7) points with passes in relevant subjects with the UTME requirements; (j) does not accept university diplomas and other diplomas not accredited by relevant accrediting bodies. O''level (with UNIOSUN): requires five (5) ''O'' Level credit passes including English Language, Mathematics, Physics to form the core subjects, with ''O'' Level credit passes in two (2) other relevant Science subjects at not more than two (2) sittings.'),
  ('540e788e-2bc0-526e-872a-00b7898fba8b', 'c56fe7bf-62ad-5caf-bfa8-3228f9f222bd', '5e4428c5-9417-5d43-8c8c-896d2d2d9266', NULL),
