INSERT INTO school_programmes (id, school_id, jamb_programme_id, remarks) VALUES
  ('eeafa1b2-f458-50b5-9c75-82e01e057f59', '4d2eede5-c18d-57fa-b36b-8863e6580ae3', 'a3ee8b52-f45a-562a-9f13-437e335f7229', '(xxiv) BOWEN accepts ''A'' Level /IJMB/NCE/ ND or approved equivalent in Mathematics and Physics. In exceptional cases Physics and Chemistry may be considered.'),
  ('d8e447bf-d51b-5a15-9b51-bffe84c177c0', '2a323993-11a4-5569-905d-e90b89ee3bc7', 'a3ee8b52-f45a-562a-9f13-437e335f7229', '(i) OAU and BSU accept ''A'' Level passes in Physics and Chemistry. | (ii) MAIDUGURI, BSU and UYO accept NCE merit with Physics major. | (vi) KUST accept NCE credit, ND/HND lower credit plus ''O'' Level credit passes in Physics, Mathematics and two (2) other Science subjects. BAYERO accepts one (1) other Science subject. BSU accepts HND upper credit only.'),
  ('79ba16bb-4536-540e-88c9-ddc110c7a845', 'dc4f0a5d-b0bd-5a7a-84e2-a4406fe8dfd8', 'a3ee8b52-f45a-562a-9f13-437e335f7229', '(xv) CALABAR requires two (2) ''A'' Level passes or their equivalents in Physics and either Chemistry or Mathematics plus ''O'' Level credit passes in Physics, English Language, Mathematics and two (2) Science subjects. (xxviii) CALABAR accepts ''A'' Level passes or its equivalent in Physics and either Chemistry or Mathematics plus ''O'' Level credit passes in Physics, English Language, Mathematics and two (2) Science subjects.'),
