  ('17309cc4-03a7-5936-9d83-d549648c6dd5', 'd27d7d4c-dcf3-5254-9faa-94e2991a92e3', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'Accepts Two ''A'' level/IJMB passes in Mathematics and any one of Chemistry, Physics, Biology, Geography and Geology. NCE in Mathematics/Statistics with any of Chemistry, Physics, Biology, Geography and Geology. ND in Mathematics/Statistics with Upper Credit plus O/L requirements. ABU Diploma in Mathematics with at least MERIT Grade. UTME SUBJECTS: Mathematics and any two (2) of Chemistry, Physics, Biology and Geography.'),
  ('3cfc5620-1e91-5b0b-bc96-2aa06b95a9d3', '4beb9b46-ddaa-5a56-b936-ea60e63b57c9', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', NULL),
