  ('c72b7d87-620c-5d3b-8499-335d4f1bd623', '494e4fb9-006d-55e9-86f2-caf559cdfb7d', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'DIRECT ENTRY: at least two ''A''/Level passes in Science subjects or GCE A/Level IJMB/Advanced NABTEB or merit pass at NCE at least Lower credit in OND/HND in Mathematics. Must satisfy UTME requirements of Five Credits including English Language and Mathematics. UTME SUBJECTS: requires Mathematics and any two of Physics, Chemistry, Biology and Economics.'),
  ('3e0c7f2e-5aa2-5b1f-bafd-cf91493780bc', '9462539f-d63e-59e0-84d5-82dfb6184f69', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'Accepts ND upper credit in Statistics, Computer Science, Mathematics or related programmes; NCE credit in relevant subjects plus UTME requirements; Two ''A'' Level passes in Statistics, Physics and Mathematics.'),
  ('84fcf13d-ba3e-5a37-9e48-b87966759822', '557c215c-aec4-5e78-9bcd-076cf7bf585b', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', NULL),
  ('cff99a32-5d0a-56fe-a989-dee3856e792b', '2a117a94-b271-5351-a623-6616184fe452', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'Accepts ND in Statistics with minimum of Upper Credit or equivalent; or GCE ''A'' Level passes in Mathematics and at least one of Physics, Economics, Geography, Chemistry and Biology at minimum grade C. UTME SUBJECTS: Physics, Mathematics and one (1) of Chemistry, Geography, Economics or Biology.'),
  ('b886bacf-6cc7-5080-a590-2d354514dd2b', 'a9560228-6453-5527-8eb6-9f5c346fabb0', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'DIRECT ENTRY: (a) at least two ''A'' level passes not below Grade C in Mathematics and Physics; (b) ND/HND Upper Credit in Physics, Mathematics, Statistics, Chemistry, Geology, Computer Science or Engineering; (c) First Degree in those fields; (d) very good passes in three JUPEB subjects: Chemistry, Physics and Mathematics. Does not accept NCE; candidates must meet ''O'' Level requirements. UTME SUBJECTS: requires Mathematics, Chemistry and Physics.'),
  ('ad28eb22-c846-59c7-801a-2f13b6735caa', 'f3d31093-b900-5185-a4ef-b3dbb37cb373', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', NULL),
  ('3469a777-b7ff-5486-b9cc-2b5b7b941e3e', '8c9295db-6a52-50d5-a409-7821d70fd2cd', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', NULL),
  ('1437aec3-0cde-57a8-b717-62f69ada7860', 'e1c071b0-e046-51f0-9de7-77ac53886688', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'DIRECT ENTRY: (a) two (2) ''A'' Level subjects to include Mathematics plus five (5) ''O'' Level credit passes including English Language. UTME SUBJECTS: does not accept Economics; requires Mathematics and any two (2) Science subjects.'),
  ('68c2c451-a52a-54a6-98a5-98e43394a842', 'be4981eb-2b54-5ea1-941d-44e8ca2774db', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', 'DIRECT ENTRY: (a) Two ''A'' level passes in Mathematics and Physics, Chemistry, Economics or Geography (IJMB, JUPEP or equivalent); (b) ND in Statistics with minimum Lower Credit; (c) NCE in Mathematics and any of Physics, Chemistry, Economics or Geography.'),
  ('e37e35ef-320e-5b9c-9439-815abfb1a8aa', 'ac7f4b89-7d4f-5edb-b392-6baaacd3af69', '66bf5d0f-7dd7-580e-9a1e-a42ffcd89cb4', NULL),
