  ('cf13d3ac-5524-525a-a7b4-41bc9c4651a8', '43eded73-d8ee-57da-ba48-e8ea86c8fc90', '017ce18b-858a-54ec-a868-66509b88f6df', 'MAUTY accepts IJMB/Two (2) A level passes from Geology, Chemistry, Mathematics and Physics. ND/HND in Geology and any other relevant field with lower credit. | MAUTY requires Five (5) SSC credit passes in English Language, Chemistry, Mathematics and any one of Geography, Biology, Mining. | MAUTY requires any three (3) of Chemistry, Physics, Mathematics, Biology and Geography.'),
  ('49ff33fb-4844-54eb-8d09-dcb07da0180f', 'bbb4456a-842d-5c68-b8df-52431f4f22b8', '017ce18b-858a-54ec-a868-66509b88f6df', 'MINNA accepts NCE credit, ND/HND lower credit plus five (5) ''O'' Level credit passes in English Language, Mathematics, Chemistry, Biology and any other Science subject and ''O'' Level pass in Physics. | MINNA requires ''O'' Level credit passes in English Language, Mathematics, Chemistry, Physics and any other relevant Science subject.'),
  ('bb18771a-2c76-554b-9265-c82be57aeb93', '357b584e-b53b-5cb4-9f49-aa8ae157f2de', '017ce18b-858a-54ec-a868-66509b88f6df', NULL),
  ('d53f07a6-e840-5747-b268-4bd6d87988a7', 'bfd398ad-cc0f-5245-bf71-04505c05d507', '017ce18b-858a-54ec-a868-66509b88f6df', 'NDU requires five (5) ''O'' Level credit passes in English Language, Mathematics, Physics, Chemistry and Biology or Geography. NDU accepts ''A'' Level, ND passes in any two (2) of Physics, Chemistry, Biology or Geography.'),
  ('049f2e6e-126e-5074-bed8-076d983c1334', '3c13885c-9b61-5e63-a6d1-c5f8b9ae2266', '017ce18b-858a-54ec-a868-66509b88f6df', 'BENIN and OAU do not accept ''A'' Level Geography. | OAU accepts HD upper credit. OAU accepts ND upper credit in Geology'),
  ('ba097d8a-a571-57d9-b2e7-eab8a9b87f24', '0b2a9d40-1151-53c2-afa0-dda8f622ef86', '017ce18b-858a-54ec-a868-66509b88f6df', 'OOU accepts ND/Professional Certificate lower credit in Geology and Mining.'),
  ('30ffb0c7-237b-5f13-bb05-9ed254ca34bb', 'e7c05fd4-6b0d-50f2-9179-d7c7be0a45a1', '017ce18b-858a-54ec-a868-66509b88f6df', 'OAUSTECH and JOS require ''O'' Level credit passes to include English Language, Mathematics, Physics, Chemistry and Biology or Geography. | OAUSTECH and KWASU require ''O'' Level credit passes in English Language, Mathematics, Physics, Chemistry and Biology or Geography.'),
  ('475c3341-d0d0-598b-85df-b789a9a6a4be', '7aeec5b4-cf56-5d90-bfa4-3371a6f54bb9', '017ce18b-858a-54ec-a868-66509b88f6df', 'PHC accepts Two (2) A/level GCE or HSC or IJMB or JUPEB passes in Physics and any one of Mathematics, Chemistry or Biology including UTME entry requirements. | PHC requires O Level credits in English Language, Mathematics, Biology, Chemistry, Physics.'),
  ('1af1917b-0310-59cf-9c5c-2e0e957b5df0', '6fbab45b-7864-5444-8af6-ae5a830fb19a', '017ce18b-858a-54ec-a868-66509b88f6df', NULL),
